#include <string.h>

char* decode_json_web_token(const char* token, const char* key) {
    jwt_t *decoded = NULL;

    // Decode the JWT token
    int result = jwt_decode(&decoded, token, (const unsigned char*)key, strlen(key), 0);

    if (result != 0) {
        return "{\"error\":\"Failed to decode JWT\"}";
    }

    // Convert decoded claims to a JSON string
    char* json_string = NULL;
    size_t length = 0;
    result = jwt_export_to_json(decoded, &json_string, &length);

    if (result != 0) {
        jwt_free_decoded_token(decoded);
        return "{\"error\":\"Failed to decode JWT\"}";
    }

    // Ensure null-termination and free the decoded token
    json_string = realloc(json_string, length + 1);
    json_string[length] = '\0';
    jwt_free_decoded_token(decoded);

    return json_string;
}
